import {digest} from '../live-paper/model.mjs';import {amount,money} from '../paper/fixed.mjs';
const r=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),candidate=JSON.parse(fs.readFileSync('data/receipt-production-candidate-20261005.json')),bank=candidate.bank;
const paperFile=path.join(r,'probability-receipt-cohorts/calibrated-kansas-poll-20261005-v1/bank.json'),paper=JSON.parse(fs.readFileSync(paperFile));
if(digest(paper)!==bank.paperBinding.bankHash)throw Error('Original paper bank changed');
const stats=JSON.parse(fs.readFileSync(path.join(path.dirname(paperFile),'stats.json'))),w=stats.wallets['3000'];
if(stats.bankHash!==digest(paper)||stats.failed||Date.now()-Date.parse(stats.updatedAt)>20000||w.pending.length)throw Error('Paper evidence unavailable');
const executable=path.resolve('backend-rust/target/receipt-strategy-20261005/release/baal-backend.exe'),dir=path.join(r,'receipt-policy-dryruns',randomUUID());fs.mkdirSync(dir,{recursive:true,mode:0o700});
const journal=path.join(r,'public-books.jsonl'),bytes=fs.readFileSync(journal),endByte=bytes.lastIndexOf(10)+1,expectedSha=sha(bytes.subarray(0,endByte)),scope=path.join(dir,'scope.json');fs.writeFileSync(scope,JSON.stringify(paper.universe)+'\n',{flag:'wx',mode:0o600});
const publication=await readNativePublicationPrefix({journal,scope,endByte,expectedSha,out:path.join(dir,'publication.json'),executable,pinnedBinaryHash:bank.nativeBackend.binaryHash});
if(publication.engineHash!==bank.nativeBackend.engineHash)throw Error('Native source graph mismatch');
