const now=Date.now(),candidates=bank.candidates.map(c=>{const node=publication.state.books[c.exchangeId+':YES'],b=node?.book||node;if(!b)throw Error('No public book');const availableAtMs=Date.parse(node.availableAt||node.publishedAt||b.receivedAt),start=Date.parse(b.requestStartedAt);
 const a=eligibility.filter(x=>Date.parse(x.positionsAt)<=start&&Date.parse(x.ordersAt)<=start).at(-1);if(!a?.complete)throw Error('No causal account eligibility');
 return{...c,book:{requestStartedAtMs:start,receivedAtMs:Date.parse(b.receivedAt),availableAtMs,sequence:Number(b.sequence),sourceHash:node.publicationHash||node.hash||publication.state.hash,representation:'direct_yes',bids:b.bids,asks:b.asks},account:{positionsAtMs:Date.parse(a.positionsAt),ordersAtMs:Date.parse(a.ordersAt),knownAtMs:Date.parse(a.ordersAt),complete:true,positionExcluded:a.excludedMarketIds.includes(c.marketId),openOrderExcluded:a.excludedMarketIds.includes(c.marketId)}};
});
const input={schemaVersion:2,mode:'probability_receipt_policy_v1',asOfMs:now,policy:bank.policy,receiptPolicy:bank.receiptPolicy,receiptState:{riskExits:{},lastExitedAtMs:{}},wallet:{capital:paper.config.initialCash,cash:w.cash,cumulativeBuys:money(w.recentFills.filter(f=>f.action==='buy').reduce((n,f)=>n+amount(f.price)*BigInt(f.quantity),0n)),positions:w.positions.map(p=>{const c=bank.candidates.find(c=>c.exchangeId+':YES'===p.instrument),f=w.recentFills.filter(f=>f.instrument===p.instrument&&f.action==='buy').at(-1);if(!c||!f)throw Error('Paper attribution missing');return{candidateId:c.id,quantity:p.quantity,cost:p.cost,enteredAtMs:Date.parse(f.at)};}),reservations:[]},candidates};
const checked=runSettlementValue({input,dir:path.join(dir,'decision'),executable});
if(checked.result.engineHash!==bank.nativeBackend.engineHash)throw Error('Native identity mismatch');
const record={schemaVersion:1,at:new Date(now).toISOString(),kind:'file_only_native_proposal_against_live_paper_evidence',paperBankHash:digest(paper),candidateBankHash:candidate.bankHash,sourceHash:expectedSha,sourceBytes:endByte,sourceSequence:publication.sourceRecords,nativeBackend:bank.nativeBackend,inputHash:checked.inputHash,outputHash:checked.outputHash,wallMs:checked.wallMs,decisions:checked.result.decisions,officialAccountPositionsUsed:false,networkRequests:0,competitionOrders:0,executionAuthority:false,profitabilityEstablished:false};
